def audit_dev2(old_pools,hold_pools,npairs=30):
    ok=True;out=[]
    for k,n in DEV2_NEED.items():
        v=DEV2_POOLS[k];ex=sorted(set(v)&(set(old_pools[k])|set(hold_pools[k])));good=len(v)>=n*npairs and len(set(v))==len(v) and not ex;ok&=good
        out.append(f'{k}: {len(v)} (need {n*npairs}), duplicates {len(v)-len(set(v))}, exact overlap with E48 / holdout pools {len(ex)} {ex} -> {"OK" if good else "CHECK"}')
    return ok,out
